/// @notice Admit the first typed, content-addressed state under the caller's derived identity.
function admitBoundResource(bytes32 kind, bytes32 subject, bytes32 content, bytes32 evidence)
    external
{
    _requireNonzero(kind, "kind");
    _requireNonzero(subject, "subject");
    _requireNonzero(content, "content");
    _requireNonzero(evidence, "evidence");

    bytes32 resource = resourceId(msg.sender, kind, subject);
    if (resources[resource].exists) revert ResourceAlreadyExists(resource);

    resources[resource] = Resource({
        controller: msg.sender,
        kind: kind,
        content: content,
        evidence: evidence,
        sequence: 1,
        exists: true
    });
    emit ResourceAdmitted(resource, msg.sender, kind, content, evidence, 1);
}

